// A shorter; search cut i in [0,m]; j = (m+n+1)/2 - i
while (lo <= hi) {
    int i = (lo + hi) / 2, j = half - i;
    int Al = i ? A[i-1] : INT_MIN, Ar = i<m ? A[i] : INT_MAX;
    int Bl = j ? B[j-1] : INT_MIN, Br = j<n ? B[j] : INT_MAX;
    if (Al <= Br && Bl <= Ar) {           // VALID partition
        return (m+n)%2 ? max(Al,Bl)
                       : (max(Al,Bl)+min(Ar,Br))/2.0;
    }
    Al > Br ? hi = i - 1 : lo = i + 1;    // shift cut toward balance
}
